// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading ensures readiness before frame 0
const { fontFamily: interFamily } = loadInter();



export type ConstructionLifecycleProps = Record<string, any>;

const ConstructionLifecycle: React.FC<ConstructionLifecycleProps> = ({
  backgroundColor = "#0d1117",
  transparentBackground = false,
  durationInSeconds = 10,
  titleText = "Project Lifecycle",
  stages = [
    "Estimating",
    "Buyout",
    "Execution of Work",
    "Punch List",
    "Closeout",
  ],
  folderColor = "#FBBF24",
  pmColor = "#60A5FA",
  activeColor = "#3B82F6",
  trackColor = "#334155",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parse background logic
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Protect against empty arrays
  const safeStages = stages.length < 2 ? [...stages, "Completion"] : stages;
  const numStages = safeStages.length;
  const travelStages = Math.max(1, numStages - 1);

  // Canvas-Aware Layout Math
  const timelineX = width * 0.25;
  const textStartX = width * 0.4;
  const startY = height * 0.25;
  const endY = height * 0.85;
  const gap = (endY - startY) / travelStages;

  // Animation Timing
  const totalFrames = Math.max(1, durationInSeconds * fps);
  // Dedicate first 25% of time to setup (folder appear, handoff to PM)
  const setupFrames = totalFrames * 0.25;
  const travelFrames = totalFrames * 0.65;
  const timePerHop = travelFrames / travelStages;

  // Calculate strict monotonically increasing arrays for vertical travel
  const yInputs: number[] = [0];
  const yOutputs: number[] = [startY];
  const arrivalFrames: number[] = [10]; // Frame when PM "arrives" at each node

  for (let i = 0; i < travelStages; i++) {
    const holdStart = setupFrames + i * timePerHop;
    const holdEnd = holdStart + timePerHop * 0.3; // Pause at node for 30% of hop time
    const travelEnd = holdStart + timePerHop;

    const startNodeY = startY + i * gap;
    const endNodeY = startY + (i + 1) * gap;

    if (holdStart > yInputs[yInputs.length - 1]) {
      yInputs.push(holdStart);
      yOutputs.push(startNodeY);
    }
    if (holdEnd > yInputs[yInputs.length - 1]) {
      yInputs.push(holdEnd);
      yOutputs.push(startNodeY);
    }
    if (travelEnd > yInputs[yInputs.length - 1]) {
      yInputs.push(travelEnd);
      yOutputs.push(endNodeY);
    }
    
    arrivalFrames.push(travelEnd);
  }

  // Ensure arrays have at least 2 elements
  if (yInputs.length === 1) {
    yInputs.push(totalFrames);
    yOutputs.push(endY);
  }

  const currentY = interpolate(frame, yInputs, yOutputs, {
    easing: Easing.inOut(Easing.ease),
    extrapolateRight: "clamp",
  });

  // Intro Springs & Interpolations
  const titleOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [0, 15], [height * 0.1, height * 0.12], {
    easing: Easing.out(Easing.ease),
    extrapolateRight: "clamp",
  });

  const trackOpacity = interpolate(frame, [10, 30], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Handoff Animation Logic
  // Folder drops in
  const folderInitialScale = spring({
    frame: frame - 15,
    fps,
    config: { damping: 12 },
  });

  // PM slides in
  const pmIntroProgress = spring({
    frame: frame - (setupFrames * 0.4),
    fps,
    config: { damping: 14, stiffness: 80 },
  });
  const pmIntroX = interpolate(
    pmIntroProgress,
    [0, 1],
    [width + 200, timelineX + 50]
  );

  // They combine
  const combineProgress = spring({
    frame: frame - (setupFrames * 0.7),
    fps,
    config: { damping: 14 },
  });
  
  const finalFolderX = interpolate(
    combineProgress,
    [0, 1],
    [timelineX, timelineX - 25]
  );
  
  const finalPmX = interpolate(
    combineProgress,
    [0, 1],
    [pmIntroX, timelineX + 25]
  );

  const finalFolderScale = interpolate(
    combineProgress,
    [0, 1],
    [folderInitialScale, 0.75 * folderInitialScale]
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        color: "#ffffff",
      }}
    >
      {/* Title */}
      <div
        style={{
          position: "absolute",
          top: titleY,
          width: "100%",
          textAlign: "center",
          fontSize: 48,
          fontWeight: 800,
          opacity: titleOpacity,
          color: activeColor,
          transition: "none",
        }}
      >
        {titleText}
      </div>

      {/* Background Track */}
      <div
        style={{
          position: "absolute",
          left: timelineX - 4,
          top: startY,
          width: 8,
          height: endY - startY,
          backgroundColor: trackColor,
          opacity: trackOpacity,
          borderRadius: 4,
          transition: "none",
        }}
      />

      {/* Active Track */}
      <div
        style={{
          position: "absolute",
          left: timelineX - 4,
          top: startY,
          width: 8,
          height: Math.max(0, currentY - startY),
          backgroundColor: activeColor,
          borderRadius: 4,
          transition: "none",
        }}
      />

      {/* Nodes and Text */}
      {safeStages.map((stage, i) => {
        const nodeY = startY + i * gap;
        const arriveFrame = arrivalFrames[i];

        // Active state scaling and color
        const nodePop = spring({
          frame: frame - arriveFrame,
          fps,
          config: { damping: 12 },
        });

        // The text fades in as a base, then brightens when active
        const baseTextOpacity = interpolate(frame, [20 + i * 5, 40 + i * 5], [0, 0.5], {
          extrapolateRight: "clamp",
        });
        const activeTextOpacity = interpolate(frame, [arriveFrame, arriveFrame + 10], [0, 1], {
          extrapolateRight: "clamp",
        });

        const isPast = frame >= arriveFrame;

        return (
          <React.Fragment key={i}>
            {/* Base Grey Node */}
            <div
              style={{
                position: "absolute",
                left: timelineX,
                top: nodeY,
                width: 24,
                height: 24,
                borderRadius: "50%",
                backgroundColor: trackColor,
                transform: `translate(-50%, -50%) scale(${trackOpacity})`,
                transition: "none",
              }}
            />
            {/* Active Blue Node */}
            <div
              style={{
                position: "absolute",
                left: timelineX,
                top: nodeY,
                width: 24,
                height: 24,
                borderRadius: "50%",
                backgroundColor: activeColor,
                transform: `translate(-50%, -50%) scale(${nodePop})`,
                transition: "none",
              }}
            />

            {/* Stage Text */}
            <div
              style={{
                position: "absolute",
                left: textStartX,
                top: nodeY,
                transform: "translateY(-50%)",
                fontSize: 36,
                fontWeight: 600,
                color: isPast ? "#ffffff" : "#9CA3AF",
                opacity: isPast ? 1 : baseTextOpacity,
                transition: "none",
              }}
            >
              {stage}
            </div>
          </React.Fragment>
        );
      })}

      {/* Traveling Actor (Folder + PM) */}
      <div
        style={{
          position: "absolute",
          top: currentY,
          left: 0,
          width: "100%",
          height: 0, // 0 height to act as an anchor point
          transition: "none",
        }}
      >
        {/* PM Icon */}
        <div
          style={{
            position: "absolute",
            left: finalPmX,
            top: 0,
            transform: `translate(-50%, -50%) scale(${pmIntroProgress})`,
            width: 72,
            height: 72,
            color: pmColor,
            transition: "none",
          }}
        >
          <svg fill="currentColor" viewBox="0 0 24 24" width="100%" height="100%">
            <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" />
          </svg>
        </div>

        {/* Folder Icon */}
        <div
          style={{
            position: "absolute",
            left: finalFolderX,
            top: 0,
            transform: `translate(-50%, -50%) scale(${finalFolderScale})`,
            width: 64,
            height: 64,
            color: folderColor,
            transition: "none",
          }}
        >
          <svg fill="currentColor" viewBox="0 0 24 24" width="100%" height="100%">
            <path d="M10 4H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V8c0-1.1-.9-2-2-2h-8l-2-2z" />
          </svg>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ConstructionLifecycle;